#!/usr/bin/env python3
import pathlib, re, sys
EXPECTED = {'CookCompletionTests': ['testEventsBuiltWithoutAnIdGetDistinctIds', 'testEventSnapshotCarriesTitleAndCookedDay', 'testEventSurvivesCodableWithItsIdentity', 'testEventAcceptsExtremeDatesWithoutTrapping', 'testOutboxKeepsAFinishUntilAcknowledgedAndAcrossInstances', 'testOutboxEnqueueIsIdempotentByIdAndKeepsDistinctCooks', 'testOutboxAcknowledgeOfUnknownIdChangesNothing', 'testUnreadableOutboxIsNeverTreatedAsEmptyAndKeepsItsExactBytes', 'testUnreadableOutboxCanBeSetAsideWithItsBytesThenAcceptsEvents', 'testQueueWithDuplicateOrEmptyIdsIsUnreadableAndKeepsItsBytes', 'testEmptyIncomingIdIsRefusedBeforeAnyWriteAndLeavesAHealthyQueueReadable', 'testSettingAsideAReadableOutboxDoesNothing', 'testRetryWithSameIdReturnsTheFirstStoredEventWholeAndChangesNothing', 'testOfferIsUsedUpOnlyWhenShownAndThenNotAgainThatDay', 'testOfferReturnsOnTheNextLocalDay', 'testOfferStateSurvivesANewPolicyInstance', 'testOfferPolicyLeavesStandardDefaultsUntouched', 'testFinishBeginsOnceAndBlocksFurtherSessionWrites', 'testPrefillNeverReplacesAnExistingDraft', 'testResumeUsesSavedStepWhenNoTimerRuns', 'testRunningTimerStepWinsOverSavedStep', 'testResumeNeverPassesTheLastStepWhenTheRecipeLostSteps', 'testResumeClampsNegativeAndMissingAndEmpty', 'testReconcileKeepsAndClampsAResumableSession', 'testReconcileDiscardsASessionWhoseRecipeIsGoneOrHasNoSteps'], 'CookSessionIdentityTests': ['testNewCooksOfSameRecipeHaveDifferentIdentity', 'testIdentitySurvivesCodableRoundTripAndSessionEdits', 'testLegacySnapshotGainsIdentityAndRetainsEveryOldField'], 'CookSessionIdentityLifecycleTests': ['testResumeRetainsIdentityReplacementAndNewCookDoNot', 'testMissingWrongRecipeAndInvalidIdentityFailBeforeAnySessionClear', 'testOldSameRecipeCompletionCannotClearNewCookAndSuccessfulClearVerifiesAbsent'], 'CookedJournalReflectionTests': ['testOptionalReflectionPreservesCompletionSnapshotWithoutMealOrHealthState', 'testRepeatedSaveSameEventReturnsSameIdentityWithoutDuplicate', 'testConflictingRetryNeverOverwritesSavedReflectionOrSnapshot', 'testFailureLeavesNoPendingReflectionOrUnrelatedContextRollback', 'testFallbackCannotSaveDurableCookAndEmptyOrInvalidContextCannotWrite', 'testNoOpSaveCannotBeAcknowledgedAsDurableReflection'], 'CookedJournalReflectionSessionTests': ['testVerifiedSaveAcknowledgesOnlyCapturedCookAndKeepsOriginalSnapshot', 'testUnconfirmedSaveKeepsDraftAndExactQueuedEvent', 'testChangedQueuedPayloadCannotWriteOrAcknowledge', 'testAcknowledgementThrowsAfterRemovalCanRetryVerifiedReflectionAndQueueAbsence', 'testAcknowledgementPendingDoesNotClearAnEditedDraft', 'testRuntimeUsesItsOwnOutboxAndActualJournalForPendingSessions', 'testHostRetainedAckPendingSessionRemainsAvailableWithoutQueueAndWaitsForModal'], 'CookReflectionUITests': ['testFinishDoesNotRecreateTheResumeSession', 'testOptionalCookReflectionSavesThroughActualModalHost', 'testKeepLaterReopensSameDraftAcrossRotation', 'testOptionalCookReflectionUsesNavigationHostAfterFinish', 'testPendingCookComposerWaitsForManualComposerThenAppears', 'testMaximumAccessibilityOfferAndComposerActionsRemainReachable']}
text = pathlib.Path(sys.argv[1]).read_text()
if '** TEST SUCCEEDED **' not in text:
    raise SystemExit('Missing TEST SUCCEEDED')
for cls, expected in EXPECTED.items():
    rows = re.findall(r"Test Case '-\[\S*" + cls + r" (\w+)\]' (passed|failed) \(([0-9.]+) seconds\)", text)
    if len(rows) != len(expected) or {r[0] for r in rows} != set(expected) or any(r[1] != 'passed' or float(r[2]) <= 0 for r in rows):
        raise SystemExit(f'Expected exact nonzero named passes for {cls}: {rows!r}')
    print(f'Verified {len(expected)} named nonzero {cls} passes')
